import { Link } from 'react-router-dom';import { useApp } from '../../contexts/AppContext';import { formatMoney, createWhatsAppOrderMessage, whatsappUrl, LocalOrder } from '../../lib/api';import { MessageCircle } from 'lucide-react';
export default function Carrinho(){const {cart,removeCart,updateQty}=useApp();const subtotal=cart.reduce((s,i)=>s+i.preco_unitario*i.quantidade,0);const frete=subtotal>0?0:0;function pedidoRapido(){const order:LocalOrder={numero:'ORC-'+Date.now(),items:cart,cliente:{nome:'Cliente',telefone:'',email:'',endereco:'A combinar',observacoes:'Pedido rápido pelo carrinho'},subtotal,frete,desconto:0,total:subtotal+frete,created_at:new Date().toISOString()};window.open(whatsappUrl(createWhatsAppOrderMessage(order)),'_blank')}return <section className="containerx py-12 fade"><h1 className="font-display text-5xl text-primary">Carrinho</h1>{!cart.length?<div className="card p-10 mt-8"><p>Seu carrinho está vazio.</p><Link className="btn btn-primary mt-4" to="/catalogo">Ver Catálogo</Link></div>:<div className="grid lg:grid-cols-3 gap-8 mt-8"><div className="lg:col-span-2 card overflow-hidden"><table className="w-full"><tbody>{cart.map(i=><tr key={i.id} className="border-b"><td className="p-4"><img src={i.imagem_principal} className="w-20 h-20 object-cover rounded-xl"/></td><td className="p-4"><b>{i.nome}</b><p className="text-sm text-gray-500">{Object.entries(i.especificacoes_selecionadas).map(([k,v])=>`${k}: ${v}`).join(' · ')}</p></td><td className="p-4"><input className="input w-20" type="number" min={1} value={i.quantidade} onChange={e=>updateQty(i.id,Number(e.target.value))}/></td><td className="p-4 font-bold">{formatMoney(i.preco_unitario*i.quantidade)}</td><td className="p-4"><button className="text-danger font-bold" onClick={()=>removeCart(i.id)}>Remover</button></td></tr>)}</tbody></table></div><aside className="card p-6 h-fit"><h2 className="font-display text-2xl">Resumo</h2><div className="grid gap-3 mt-5"><input className="input" placeholder="Cupom de desconto"/><p className="flex justify-between"><span>Subtotal</span><b>{formatMoney(subtotal)}</b></p><p className="flex justify-between"><span>Frete</span><b>A combinar</b></p><p className="flex justify-between text-xl border-t pt-4"><span>Total parcial</span><b>{formatMoney(subtotal+frete)}</b></p><Link className="btn btn-primary w-full" to="/checkout">Finalizar pelo WhatsApp</Link><button className="btn btn-whats w-full" onClick={pedidoRapido}><MessageCircle size={18}/>Enviar carrinho</button><Link className="btn btn-dark w-full" to="/catalogo">Continuar Comprando</Link></div></aside></div>}</section>}
